SELECT MONTH(opened_date) AS opened_month, city, COUNT(DISTINCT sqft) AS unique_regions, ROUND((100 * SUM(CASE WHEN city = 'Chiang Mai' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_chiang_mai FROM stores WHERE (region = 'North' AND sqft = 14324) OR store_name IS NOT NULL GROUP BY 1, 2 HAVING ROUND((100 * SUM(CASE WHEN city = 'Chiang Mai' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 47 ORDER BY city DESC;
